22	import { captureUnexpectedError } from '@/lib/observability/sentry';
23	import {
24	    EnquiryInput,
25	    EnquirySchema,
26	    SendEnquiryProxy,
27	} from '@/types/actions/SendEnquiry';
28	
29	export interface Props {
30	    onSendEnquiry: SendEnquiryProxy;
31	}
32	
33	export const EnquiryForm = ({ onSendEnquiry }: Props) => {
34	    const pathname = usePathname();
35	    const [submitting, setSubmitting] = useState(false);
36	    const form = useForm<EnquiryInput>({
37	        initialValues: {
38	            name: '',
39	            email: '',
40	            message: '',
41	        },
42	        validate: zod4Resolver(EnquirySchema),
43	        validateInputOnBlur: true,
44	    });
45	
46	    const handleSubmit = async (values: EnquiryInput) => {
47	        const id = notifications.show({
48	            loading: true,
49	            title: 'Sending enquiry',
50	            message: 'Sending your message...',
51	            autoClose: false,
52	            withCloseButton: false,
53	        });
54	
55	        setSubmitting(true);
56	        try {
57	            await onSendEnquiry(values);
58	            form.reset();
59	
60	            notifications.update({
61	                id,
62	                color: 'teal',
63	                title: 'Confirm your email',
64	                message:
65	                    'Check your inbox and verify your email to deliver the message.',
66	                icon: <IconCheck size={config.notificationIconSize} />,
67	                loading: false,
68	                autoClose: false,
69	            });
70	        } catch (error) {
71	            captureUnexpectedError(error, {
72	                layer: 'client',
73	                component: 'EnquiryForm',
74	                action: 'sendEnquiry',
75	                route: pathname,
76	            });
77	            const message = toPublicMessage(
78	                error,
79	                'Unable to send your message.',
80	            );
81	            notifications.update({
82	                id,
83	                color: 'red',
84	                title: 'Error',
85	                message,
86	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
87	                loading: false,
88	                autoClose: false,
89	                withCloseButton: true,
90	            });
91	        } finally {
92	            setSubmitting(false);
93	        }
94	    };
95	
96	    return (
97	        <Box
98	            maw={520}
99	            component="form"
100	            onSubmit={form.onSubmit(handleSubmit)}
101	            noValidate
102	        >
103	            <Stack>
104	                <Title order={3}>Get in touch</Title>
105	                <Text>
106	                    Want to join, have a question, or just say hello? Send us a
107	                    message and we will reply soon.
108	                </Text>
109	                <TextInput
110	                    label="Name"
111	                    required
112	                    {...form.getInputProps('name')}
113	                />
114	                <EmailInput
115	                    label="Email"
116	                    required
117	                    {...form.getInputProps('email')}
118	                />
119	                <Textarea
120	                    label="Message"
121	                    required
122	                    autosize
123	                    minRows={4}
124	                    {...form.getInputProps('message')}
125	                />
126	                <Button
127	                    type="submit"
128	                    loading={submitting}
129	                >
130	                    Send message
131	                </Button>
132	            </Stack>
133	        </Box>
134	    );
135	};
