1	import { asAdmin, asGuest, asUser, mustBeLoggedInAsAdmin } from './utils/auth';
2	import { expect, test } from './utils/base';
3	
4	type ResponseOption = 'Yes' | 'No' | 'Dunno';
5	
6	test.describe('Responses admin page', () => {
7	    test('denies access to guest users', async ({ page }) => {
8	        await asGuest(page, '/footy/admin/responses');
9	
10	        await mustBeLoggedInAsAdmin(page);
11	    });
12	
13	    test('denies access to regular users', async ({ page }) => {
14	        await asUser(page, '/footy/admin/responses');
15	
16	        await mustBeLoggedInAsAdmin(page);
17	    });
18	
19	    test('admin can update responses form through realistic response changes', async ({
20	        page,
21	    }) => {
22	        await asAdmin(page, '/footy/admin/responses');
23	
24	        await expect(
25	            page.getByRole('heading', { name: /Responses/i }).first(),
26	        ).toBeVisible();
27	
28	        // Read a group's player count from its h2 heading ("Yes: 15").
29	        // CSS + text filter works regardless of whether the card has an explicit ARIA role.
30	        const groupCount = async (title: string) => {
31	            const heading = page
32	                .locator('h2')
33	                .filter({ hasText: new RegExp(`^${title}:\\s*`) });
34	            if ((await heading.count()) === 0) return 0;
35	            const text = await heading.first().innerText();
36	            const match = /:\s*(\d+)$/.exec(text.trim());
37	            return match ? Number(match[1]) : 0;
38	        };
39	
40	        const initialYes = await groupCount('Yes');
41	        const initialNo = await groupCount('No');
42	        const initialDunno = await groupCount('Dunno');
43	        const initialNone = await groupCount('None');
44	
45	        const startsFromNone = initialNone > 0;
46	        const yesAfterFirstUpdate = startsFromNone
47	            ? initialYes + 1
48	            : initialYes;
49	        const noneAfterFirstUpdate = startsFromNone
50	            ? initialNone - 1
51	            : initialNone;
52	
53	        // Yes group renders before None; skip past Yes rows to reach the first None player.
54	        // Group cards are collapsed by default, but data-player-id attributes are readable
55	        // on hidden elements without needing the group expanded first.
56	        const targetRow = page
57	            .locator('[data-player-id]')
58	            .nth(startsFromNone ? initialYes : 0);
59	        const playerId = await targetRow.getAttribute('data-player-id');
60	
61	        if (!playerId) {
62	            throw new Error(
63	                'Expected player row to have a data-player-id attribute.',
64	            );
65	        }
66	
67	        // Tracks the player by ID across group changes — they appear in exactly one group at a time.
68	        const playerRow = page.locator(`[data-player-id="${playerId}"]`);
69	
70	        // Groups render collapsed; expand the one containing the player before interacting
71	        // with its row. A group heading's accessible name is "<Title>: <count>".
72	        const expandGroup = async (title: string) => {
73	            const button = page.getByRole('button', {
74	                name: new RegExp(`^${title}:`),
75	            });
76	            await expect(button.first()).toBeVisible({ timeout: 10000 });
77	            if (
78	                (await button.first().getAttribute('aria-expanded')) !== 'true'
79	            ) {
80	                await button.first().click();
81	            }
82	        };
83	
84	        await expandGroup(startsFromNone ? 'None' : 'Yes');
85	
86	        const setResponseValue = async (response: ResponseOption) => {
87	            const combobox = playerRow.getByRole('combobox', {
88	                name: /response/i,
89	            });
90	
91	            // Shared fixture data means the target player's response may already match
92	            // (e.g. carried over from an earlier project in the same suite run); re-selecting
93	            // an already-selected option is unreliable, so skip the interaction entirely.
94	            if ((await combobox.inputValue()) === response) return;
95	
96	            // The SSE-triggered refresh (see the comment in updatePlayer below) can land
97	            // mid-interaction and remount the row, closing the dropdown before the option
98	            // is clicked. Retry the open-then-select sequence rather than failing outright.
99	            await expect(async () => {
100	                await combobox.click();
101	                await page
102	                    .getByRole('option', { name: response, exact: true })
103	                    .click({ timeout: 3000 });
104	            }).toPass({ timeout: 20000 });
105	        };
106	
107	        const updatePlayer = async (
108	            response: ResponseOption,
109	            goalie: boolean,
110	            comment: string,
111	        ) => {
112	            await setResponseValue(response);
113	            if (goalie) {
114	                await playerRow
115	                    .getByRole('checkbox', { name: /goalie/i })
116	                    .check();
117	            } else {
118	                await playerRow
119	                    .getByRole('checkbox', { name: /goalie/i })
120	                    .uncheck();
121	            }
122	            await playerRow.getByPlaceholder('Comment').fill(comment);
123	            await playerRow.getByRole('button', { name: 'Update' }).click();
124	            // Wait for handleSubmit to fully resolve before the next update.
125	            // The server broadcasts before returning its RPC response, so the
126	            // SSE-triggered page refresh can arrive while the button is still
127	            // loading. Clicking Update on a loading Mantine button is a no-op.
128	            await expect(
129	                page.getByText('Response updated successfully'),
130	            ).toBeVisible({ timeout: 15000 });
131	        };
132	
133	        await updatePlayer('Yes', true, 'Can play and cover goal first half');
134	
