140	            .toBe(initialNo);
141	        await expect
142	            .poll(async () => groupCount('Dunno'), { timeout: 10000 })
143	            .toBe(initialDunno);
144	        await expect
145	            .poll(async () => groupCount('None'), { timeout: 10000 })
146	            .toBe(noneAfterFirstUpdate);
147	
