7	// Survive hot-module reloads in development without leaking multiple emitters.
8	const g = global as typeof global & { footyEmitter?: EventEmitter };
9	const emitter: EventEmitter = g.footyEmitter ?? new EventEmitter();
10	g.footyEmitter = emitter;
11	
12	/**
13	 * Publish an event on one or more named channels. Call this from server
14	 * actions or services immediately after a database mutation to push live
15	 * updates to all connected clients subscribed to those channels.
16	 */
17	export function broadcast(channels: FootyChannel | FootyChannel[]): void {
18	    const list = Array.isArray(channels) ? channels : [channels];
19	    list.forEach((channel) => emitter.emit(channel));
20	}
